head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf90011";
scwin.updateA = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.updateA = $c.util.getComponent('updateA');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf90011.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const op = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent);
        const title = op.$('#title').val();
        $c.util.getComponent('txt_titleH2').setLabel(title + " 변경확인");
        let udYn = false;
        const bfInp = op.$('input[key=bf]');
        for (let i = 0; i < bfInp.length; i++) {
            const targetId = $(bfInp[i]).attr("target");
            const colNm = op.$('[for="' + targetId + '"]').text();
            let bfVal = $(bfInp[i]).val().replace(/\,/g, '');
            if (targetId === "cfi_cd") {
                if (!op.$('#cfiCheck')[0].checked) {
                    continue;
                }
            }
            const tObj = op.$('[name="' + targetId + '"]');
            const nodeName = $(tObj)[0].nodeName;
            const nodeType = op.$('[name="' + targetId + '"]').attr("type");
            let targetVal = "";
            if (nodeName.toLowerCase() === "input") {
                if (nodeType.toLowerCase() === 'text' || nodeType.toLowerCase() === 'hidden') {
                    bfVal = bfVal.replace(/\-/g, '');
                    targetVal = $(tObj).val();
                    targetVal = targetVal.replace(/\,/g, '');
                    targetVal = targetVal.replace(/\-/g, '');
                } else {
                    if (nodeType.toLowerCase() === 'radio') {
                        targetVal = op.$('[name=' + targetId + ']:checked').next().text();
                    } else {
                        if (nodeType.toLowerCase() === 'checkbox') {
                            await $c.win.alert("체크박스 개발해야함.");
                        }
                    }
                }
            } else {
                if (nodeName === "SELECT") {
                    targetVal = op.$('[name="' + targetId + '"]').find('option:selected').text();
                }
            }
            targetVal = targetVal.replace(/\,/g, '');
            let cpVal = "N";
            if (bfVal !== targetVal) {
                cpVal = "<b><font color='red'>Y</font></b>";
                udYn = true;
            }
            const data = "<tr class='last'><td style='border:solid 1px; border-color:#cacaca;'>" + colNm + "</td><td style='border:solid 1px; border-color:#cacaca;'>" + bfVal + "</td><td style='border:solid 1px; border-color:#cacaca;'>" + targetVal + "</td><td style='border:solid 1px; border-color:#cacaca;text-align:center'>" + cpVal + "</td></tr>";
            $('#tbody').append(data);
        }
        if (!udYn) {
            scwin.updateA.setStyle("display", "none");
            $c.util.getComponent('txt_upCmt').setLabel("변경된 내역이 없어서 수정 할수 없습니다.");
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90011.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name updateA_onclick
 * @description updateA 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.updateA_onclick = function(e){
    try {
        scwin.goUpdate()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90011.updateA_onclick' }); }
};

/**
 * @method
 * @name btn_cancelPop_onclick
 * @description btn_cancelPop 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancelPop_onclick = function(e){
    try {
        scwin.cancelPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90011.btn_cancelPop_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goUpdate
 * @description go Update 처리
 * @returns {void}
 * @hidden N
 */
scwin.goUpdate = function () {
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).goUpdate();
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent)._popupWindow.close();
};

/**
 * @method
 * @name cancelPop
 * @description cancel Pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancelPop = function () {
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent)._popupWindow.close();
};
